head.b:skin:
:root{
  --paper:#f6f4ee;
  --paper-soft:#fbfaf6;
  --ink:#1c2b22;
  --ink-soft:#5a5a4f;
  --green:#1f3a29;
  --green-mid:#2b4a34;
  --green-light:#3f6b4a;
  --gold:#c8912b;
  --gold-soft:#e6c068;
  --accent:#b3541e;
  --line:#dbd5c2;
  --card:#ffffff;
  --shadow:0 10px 30px rgba(28,43,34,.08);
  --shadow-lg:0 20px 50px rgba(28,43,34,.14);
}
*{box-sizing:border-box;}
html{scroll-behavior:smooth;}
html,body{margin:0;padding:0;}
body{
  font-family:'Inter',-apple-system,BlinkMacSystemFont,sans-serif;
  background:var(--paper);
  color:var(--ink);
  line-height:1.6;
  -webkit-font-smoothing:antialiased;
}
a{color:inherit; text-decoration:none;}
img{max-width:100%;}
.container{max-width:1120px; margin:0 auto; padding:0 24px;}

/* ---------- Header ---------- */
.site-header{
  background:linear-gradient(180deg,var(--green) 0%,var(--green-mid) 100%);
  color:#fdfaf3;
  padding:18px 0;
  position:sticky; top:0; z-index:50;
  box-shadow:0 2px 18px rgba(0,0,0,.12);
}
.site-header .row{
  display:flex; justify-content:space-between; align-items:center; gap:14px; flex-wrap:wrap;
}
.brand{
  font-family:'Fraunces',Georgia,serif;
  font-size:1.35rem;
  font-weight:700;
  letter-spacing:.01em;
  display:flex; align-items:center; gap:8px;
}
.brand .dot{
  width:9px;height:9px;border-radius:50%;
  background:var(--gold-soft);
  box-shadow:0 0 0 4px rgba(230,192,104,.25);
}
.nav-pills{
  display:flex; gap:6px; flex-wrap:wrap; justify-content:flex-end;
}
.nav-pills a{
  font-size:.76rem;
  padding:7px 13px;
  border-radius:999px;
  background:rgba(255,255,255,.08);
  border:1px solid rgba(255,255,255,.16);
  color:#e9f0e9;
  white-space:nowrap;
  transition:background .15s ease, transform .15s ease;
}
.nav-pills a:hover{ background:rgba(255,255,255,.18); transform:translateY(-1px); }

/* ---------- Hero ---------- */
.hero{
  background:
    radial-gradient(circle at 15% 20%, rgba(200,145,43,.16), transparent 45%),
    radial-gradient(circle at 85% 0%, rgba(63,107,74,.18), transparent 40%),
    var(--paper);
  padding:64px 0 46px;
  border-bottom:1px solid var(--line);
}
.hero-eyebrow{
  display:inline-block;
  font-size:.72rem;
  letter-spacing:.14em;
  text-transform:uppercase;
  color:var(--accent);
  background:#fbe9d8;
  padding:6px 14px;
  border-radius:999px;
  margin-bottom:18px;
  font-weight:600;
}
.hero h1{
  font-family:'Fraunces',Georgia,serif;
  font-size:2.6rem;
  line-height:1.12;
  color:var(--green);
  margin:0 0 16px;
  max-width:680px;
}
.hero p.lead{
  font-size:1.05rem;
  color:var(--ink-soft);
  max-width:560px;
  margin:0 0 30px;
}
.hero-stats{
  display:flex; gap:14px; flex-wrap:wrap;
}
.stat-pill{
  background:var(--card);
  border:1px solid var(--line);
  border-radius:14px;
  padding:14px 20px;
  box-shadow:var(--shadow);
  min-width:130px;
}
.stat-pill .num{
  font-family:'Fraunces',Georgia,serif;
  font-size:1.5rem;
  color:var(--green);
  font-weight:700;
  display:block;
}
.stat-pill .label{
  font-size:.72rem;
  color:var(--ink-soft);
  text-transform:uppercase;
  letter-spacing:.06em;
}

/* ---------- Main blog content (individual tool pages / posts) ---------- */
main.page-main{ padding:44px 0 10px; }
.page-title{
  font-family:'Fraunces',Georgia,serif;
  font-size:1.9rem;
  color:var(--green);
  margin:0 0 18px;
  border-bottom:3px solid var(--green);
  padding-bottom:12px;
}
.post-card{
  background:var(--card);
  border:1px solid var(--line);
  border-radius:12px;
  padding:30px;
  margin-bottom:10px;
  box-shadow:var(--shadow);
}
.post-body img{max-width:100%; border-radius:8px;}
.post-body h2, .post-body h3{ color:var(--green); font-family:'Fraunces',Georgia,serif; }
.post-body pre, .post-body code{
  background:#111c14; color:#eef6ea; padding:2px 6px; border-radius:3px; font-size:.9em;
}
.post-body a{ color:var(--accent); text-decoration:underline; }

/* ---------- Tools showcase ---------- */
.tools-showcase{ padding:26px 0 70px; }
.showcase-head{
  text-align:center;
  max-width:620px;
  margin:0 auto 46px;
}
.showcase-head h2{
  font-family:'Fraunces',Georgia,serif;
  font-size:2rem;
  color:var(--green);
  margin:0 0 10px;
}
.showcase-head p{
  color:var(--ink-soft);
  font-size:.95rem;
  margin:0;
}
.tool-category{ margin-bottom:52px; scroll-margin-top:90px; }
.category-head{
  display:flex; align-items:baseline; gap:12px; margin-bottom:20px;
  border-bottom:2px solid var(--line);
  padding-bottom:10px;
}
.category-head h3{
  font-family:'Fraunces',Georgia,serif;
  font-size:1.3rem;
  color:var(--green);
  margin:0;
}
.category-head .cat-count{
  font-size:.75rem;
  color:var(--ink-soft);
  background:var(--paper-soft);
  border:1px solid var(--line);
  padding:3px 10px;
  border-radius:999px;
}
.tools-grid{
  display:grid;
  grid-template-columns:repeat(auto-fit,minmax(240px,1fr));
  gap:18px;
}
.tool-card{
  position:relative;
  background:var(--card);
  border:1px solid var(--line);
  border-radius:14px;
  padding:24px 22px;
  box-shadow:var(--shadow);
  transition:transform .18s ease, box-shadow .18s ease, border-color .18s ease;
  display:flex; flex-direction:column; gap:10px;
  min-height:168px;
}
.tool-card:hover{
  transform:translateY(-4px);
  box-shadow:var(--shadow-lg);
  border-color:var(--gold-soft);
}
.tool-card .icon-badge{
  width:44px; height:44px;
  border-radius:12px;
  background:linear-gradient(145deg,var(--green-mid),var(--green));
  display:flex; align-items:center; justify-content:center;
  font-size:1.3rem;
  box-shadow:0 6px 14px rgba(31,58,41,.25);
}
.tool-card h4{
  margin:0;
  font-size:1.02rem;
  color:var(--green);
  font-family:'Fraunces',Georgia,serif;
}
.tool-card p{
  margin:0;
  font-size:.83rem;
  color:var(--ink-soft);
  flex-grow:1;
}
.tool-card .badge{
  position:absolute;
  top:16px; right:16px;
  font-size:.62rem;
  letter-spacing:.05em;
  text-transform:uppercase;
  padding:4px 9px;
  border-radius:999px;
  font-weight:700;
}
.badge.live{ background:#e3f2e6; color:#1f6b3a; }
.badge.soon{ background:#f3ede0; color:var(--gold); }
.tool-card .cta{
  font-size:.8rem;
  font-weight:600;
  color:var(--green);
  display:inline-flex; align-items:center; gap:6px;
  margin-top:4px;
}
.tool-card.disabled{ cursor:default; opacity:.72; }
.tool-card.disabled:hover{ transform:none; box-shadow:var(--shadow); border-color:var(--line); }
.tool-card.disabled .cta{ color:var(--ink-soft); }

/* ---------- Footer ---------- */
.site-footer{
  background:var(--green);
  color:#cfe0d2;
  padding:34px 0;
  text-align:center;
  font-size:.82rem;
}
.site-footer .foot-brand{
  font-family:'Fraunces',Georgia,serif;
  color:#fff;
  font-size:1.05rem;
  margin-bottom:6px;
}

@media(max-width:760px){
  .hero h1{ font-size:2rem; }
  .nav-pills{ display:none; }
  .post-card{ padding:20px; }
}
